events=[]
class B(bytes):
 def __len__(self):
  events.append('len')
  return 1
 def __bytes__(self):
  events.append('bytes')
  return b'Z'
 def __str__(self):
  events.append('str')
  return 'Z'
 def __index__(self):
  events.append('index')
  return 90
 def __getitem__(self,key):
  events.append('getitem')
  return 90
 def __buffer__(self,flags):
  events.append('buffer')
  return memoryview(b'Z')
try:
 answer=ord(B(b''))
 result=(type(answer).__name__,answer,events)
except Exception as e:
 result=(type(e).__name__,e.args,events)

